export function createReviewsCompareProvider(domain){return createAnalyticalProviderBoundary({descriptor:{providerId:'w04.reviews.analysis',domainKind:'Review',schemaVersion:'1.2.0',comparatorVersion:'1.1.0',identityShape:'{id,revisionId}'},validateExactRef(ref){if(!ref||typeof ref.id!=='string'||typeof ref.revisionId!=='string')throw Error('REVIEW_EXACT_REF_REQUIRED');return {id:ref.id,revisionId:ref.revisionId};},refKey(ref){return canonicalAnalyticalIdentityKey('w04-reviews',[ref.id,ref.revisionId]);},resolve(ref){const r=domain.records.find(x=>x.id===ref.id&&x.revisionId===ref.revisionId);if(!r)return {state:'MISSING',reason:'Exact Review revision is not present.',reasonCode:'EXACT_REVISION_MISSING',provenanceRefs:[]};return {state:'RESOLVED',objectId:r.id,revisionId:r.revisionId,schemaVersion:'1.2.0',fields:[['state','Review state',r.state],['findingCount','Finding count',r.findings.length],['decision','Effective decision',r.decision?.outcome??'NONE'],['priorDecision','Prior effective decision',r.priorDecisionRef??'NONE'],['criterionScope','Pinned criteria',r.criteriaRefs.join('|')],['evidenceBasis','Pinned evidence',r.evidenceRefs.join('|')]].map(([path,label,value])=>({path,label,type:typeof value==='number'?'number':'string',present:true,value,provenanceRefs:[{reviewId:r.id,revisionId:r.revisionId}]})),provenanceRefs:[{reviewId:r.id,revisionId:r.revisionId,evidenceRefs:clone(r.evidenceRefs)}],domainContext:{owner:REVIEW_DOMAIN_OWNER,authority:'FORMAL_REVIEW_DOMAIN_ONLY',gatePs003Claim:false}};},preflightCompatibility(){return {compatible:true,comparatorVersion:'1.1.0'};}});}
